// Supplier master: bank details on file and last unit price. In real use, load this from
// your accounting contacts or a sheet you control. Made-up values only.
const suppliers = [
  { supplier: "Timber Co", bank_account: "BSB 000-001 ACC 11111111", last_unit_price: 42.80 },
  { supplier: "Fixings Direct", bank_account: "BSB 000-002 ACC 22222222", last_unit_price: 6.70 },
  { supplier: "Harbour Electrical", bank_account: "BSB 000-003 ACC 33333333", last_unit_price: null },
  { supplier: "Coastal Plumbing", bank_account: "BSB 000-004 ACC 44444444", last_unit_price: null },
  { supplier: "Office Supplies AU", bank_account: "BSB 000-005 ACC 55555555", last_unit_price: null },
  { supplier: "Waste Services", bank_account: "BSB 000-006 ACC 66666666", last_unit_price: null },
];

// Shared logic for the "Run five checks" Code node. Kept here so it can be tested outside n8n.
function runChecks(bills, suppliers, opts = {}) {
  const LIMIT = opts.approvalLimit ?? 10000;      // dollars; bills above this need a second approver
  const PRICE_JUMP = opts.priceJump ?? 0.10;       // flag unit price rises above 10% on the last order
  const DUP_DAYS = opts.duplicateWindowDays ?? 30; // same supplier + amount within this many days
  const bySupplier = Object.fromEntries(suppliers.map(s => [s.supplier, s]));
  const day = d => new Date(d + "T00:00:00Z").getTime() / 864e5;
  return bills.map((b, i) => {
    const reasons = [], review = [];
    const s = bySupplier[b.supplier];
    if (!s) reasons.push("New supplier: check ABN and that someone ordered this");
    if (s && b.bank_account !== s.bank_account) reasons.push("Bank details differ from the ones on file: phone the supplier on a number you already have");
    if (b.amount > LIMIT) reasons.push(`Over the $${LIMIT.toLocaleString("en-AU")} approval limit: needs a second approver`);
    const dup = bills.find((o, j) => j !== i && o.supplier === b.supplier &&
      (o.invoice === b.invoice || (o.amount === b.amount && Math.abs(day(o.date) - day(b.date)) <= DUP_DAYS)));
    if (dup && bills.indexOf(dup) < i) reasons.push(`Possible duplicate of ${dup.invoice}`);
    if (s && s.last_unit_price && b.unit_price && b.unit_price > s.last_unit_price * (1 + PRICE_JUMP))
      review.push(`Unit price up ${Math.round((b.unit_price / s.last_unit_price - 1) * 100)}% on the last order`);
    const status = reasons.length ? "Held" : review.length ? "Review" : "Ready to pay";
    return { ...b, status, reasons: [...reasons, ...review].join("; ") };
  });
}

const bills = $input.all().map(i => i.json);
return runChecks(bills, suppliers, { approvalLimit: 10000, priceJump: 0.10, duplicateWindowDays: 30 }).map(r => ({ json: r }));

// One line per status, ready for an email or Teams/Slack message. Nothing is paid here:
// a person approves the payment run in the accounting system.
const rows = $input.all().map(i => i.json);
const total = s => rows.filter(r => r.status === s).reduce((a, r) => a + r.amount, 0);
const fmt = n => '$' + n.toLocaleString('en-AU');
const held = rows.filter(r => r.status !== 'Ready to pay').map(r => `${r.invoice} ${r.supplier} ${fmt(r.amount)}: ${r.reasons}`);
return [{ json: {
  ready_count: rows.filter(r => r.status === 'Ready to pay').length,
  ready_total: total('Ready to pay'),
  held_count: held.length,
  held_total: total('Held') + total('Review'),
  held_detail: held,
  message: `${rows.filter(r => r.status === 'Ready to pay').length} bills (${fmt(total('Ready to pay'))}) ready for your approval. ${held.length} held for a person:\n` + held.join('\n')
} }];
